<!doctype html><html><head><meta charset="utf-8"><style>@page{margin:32px}body{font-family:DejaVu Sans,sans-serif;color:#17211f;font-size:12px}h1{margin:0;font-size:24px}.meta{color:#56615e;margin:4px 0 24px}.card{border:1px solid #d5d9d3;padding:16px;margin:14px 0}table{width:100%;border-collapse:collapse}th,td{padding:8px;border-bottom:1px solid #ddd;text-align:left}.money{text-align:right}.total{font-weight:bold;font-size:15px}.note{margin-top:28px;color:#56615e;font-size:10px}</style></head><body><h1>Confidential payslip</h1><p class="meta">Payroll period {{ $payslip['period_start'] }} to {{ $payslip['period_end'] }}</p><div class="card"><strong>{{ $payslip['staff']['name'] }}</strong><br>Employee {{ $payslip['staff']['employee_number'] }}</div><table><tr><th>Description</th><th class="money">PKR</th></tr><tr><td>Gross earnings</td><td class="money">{{ $payslip['totals']['gross'] }}</td></tr><tr><td>Deductions</td><td class="money">{{ $payslip['totals']['deductions'] }}</td></tr><tr class="total"><td>Net pay</td><td class="money">{{ $payslip['totals']['net'] }}</td></tr><tr><td>Recorded paid</td><td class="money">{{ $payslip['totals']['paid'] }}</td></tr><tr><td>Outstanding liability</td><td class="money">{{ $payslip['totals']['outstanding'] }}</td></tr></table><p class="note">This document records operational payroll. Statutory amounts shown were entered or imported; the system did not calculate legal tax or contribution obligations. A recorded external payout is not a bank transfer confirmation.</p></body></html>
